from pydantic.fields import Field", "replace": "from pydantic import BaseModel, ConfigDict, Field", "explanation": "`pydantic.fields.Field` is an internal import path. Pydantic V2 exposes `Field` from the top-level `pydantic` package (migration guide), so import it there and drop the separate `pydantic.fields` import."}, {"finding_ids": ["pydantic_cli/examples/simple_with_boolean_custom.py:5:moved-import"], "search": "    input_file3: str = Field(
        ..., description="Path to input H5 file", cli=("-f", "--hdf5")
